import React, { useEffect, useState } from "react";
import ProductsTable from "./UsersTable";
import useApi from "../../hooks/useApi";
import { useNavigate } from "react-router-dom";
import UsersFormModal from "./UsersFormModal";
import productsApi from "../../api/productsApi";
import { Loading } from "../../components";
import usersApi from "../../api/usersApi";
import paymentsApi from "../../api/paymentsApi";
import { toast } from "react-toastify";

const columns = [
  { name: "names", uid: "names" },
  { name: "First Name", uid: "first_name" },
  { name: "Last Name", uid: "last_name" },
  { name: "Email", uid: "email" },
  { name: "Phone", uid: "phone" },
  { name: "IPRS Verified", uid: "iprs_verified" },
  { name: "Entity", uid: "entity_title" },
  { name: "Actions", uid: "actions" },
];

function UsersList() {
  const [openEditModal, setopenEditModal] = useState(false);
  const [modalTitle, setmodalTitle] = useState("");
  const navigate = useNavigate();
  const [product, setProduct] = useState();
  const [users, setUsers] = useState([]);
  const [data, setdata] = useState([]);
  const [updated, setUpdated] = useState(false);
  const [errors, setErrors] = useState([]);
  const getAllUsersApi = useApi(usersApi.usersAdminAction);
  const [user, setUser] = useState();

  const getAllUsers = async () => {
    await getAllUsersApi.request({
      action: "GetAllUsers",
    });
  };

  useEffect(() => {
    getAllUsers();
  }, []);

  const createProfileApi = useApi(paymentsApi.paymentsServicesProvidersAction);
  const createUserProfile = async (item) => {
    await createProfileApi.request({
      action: "CreatePaymentServiceProviderProfile",
      user: item.id,
    });
  };

  useEffect(() => {
    if (createProfileApi.data) {
      if (createProfileApi.data.errors && createProfileApi.data.errors.length) {
        setErrors(createProfileApi.data.errors);
      }
    }
    console.log("createProfileApi.data", createProfileApi.data);
  }, [createProfileApi.data]);

  useEffect(() => {
    if (errors && errors.length) {
      errors.map((x) => {
        toast.error(x);
      });
    }
  }, [errors]);

  const handleEditAction = (item) => {
    setopenEditModal(true);
    setUser(item);
    setmodalTitle(`Edit ${item.tittle}`);
    console.log("iten", item);
    // console.log('Item', item)
    // navigate(`/categories/edit/${item.id}`, {
    //     state: {
    //         'item': item
    //     }
    // })
    createUserProfile(item);
  };

  const handleAddAction = () => {
    setUpdated(false);
    setopenEditModal(true);
    setmodalTitle("Add new entity");
    setProduct(null);
  };
  const handleDetailsAction = (item) => {
    navigate(`/users/details/${item.id}`, {
      state: {
        item: item,
      },
    });
  };
  const handleDeleteAction = (item) => {
    navigate(`/products/delete/${item.id}`);
  };

  useEffect(() => {
    if (getAllUsersApi.data && getAllUsersApi.data.length) {
      setUsers(getAllUsersApi.data);
    }

    console.log("getAllUsersApi.data", getAllUsersApi.data);
  }, [getAllUsersApi.data]);

  useEffect(() => {
    getAllUsers();
  }, [updated]);

  //Filtering data
  useEffect(() => {
    setdata(users);
  }, [users]);

  const handleFilter = (e) => {
    const search_param = e;

    if (search_param) {
      setdata(
        users.filter((x) => x.title.toLowerCase().includes(search_param))
      );
    } else {
      setdata(getAllUsersApi.data);
    }
  };

  return (
    <div>
      {openEditModal && (
        <UsersFormModal
          ismodalOpen={openEditModal}
          setisModalOpen={setopenEditModal}
          productToEdit={product}
          updated={updated}
          setUpdated={setUpdated}
          modalTitle={modalTitle}
        />
      )}
      {getAllUsersApi.loading ? (
        <Loading loading={getAllUsersApi.loading} />
      ) : (
        <ProductsTable
          data={data}
          columns={columns}
          editAction={handleEditAction}
          detailsAction={handleDetailsAction}
          deleteAction={handleDeleteAction}
          addAction={handleAddAction}
          handleFilter={handleFilter}
        />
      )}
    </div>
  );
}

export default UsersList;
