import React, { useEffect, useState } from "react";
import * as Yup from "yup";
import { Button } from "@heroui/react";
import {
  CustomForm,
  CustomFormItem,
  CustomInput,
  CustomSelectAsyncSelect,
  CustomSelectReactSelect,
  FileUploader,
  CustomTextArea,
  Loading,
} from "../../components";
import { useFormik } from "formik";
import useApi from "../../hooks/useApi";
import { ToastContainer, toast } from "react-toastify";
import makeAnimated from "react-select/animated";
import genericsApi from "../../api/drugs/genericsApi";
import preparationsApi from "../../api/drugs/preparationsApi";
import categoriesApi from "../../api/categoriesApi";
import entitiesApi from "../../api/entitiesApi";
import { useDispatch, useSelector } from "react-redux";
import {
  addProduct,
  updateProduct,
  resetRedux,
} from "../../redux/manufacturers/products/actions";
import { Modal } from "antd";

export default function UsersFormModal({
  ismodalOpen,
  setisModalOpen,
  productToEdit,
  modalTitle = "Add new branch",
  updated,
  setUpdated,
}) {
  const animatedComponent = makeAnimated();
  const errors = useSelector((state) => state.Products.errors);
  const loading = useSelector((state) => state.Products.loading);
  const response_code = useSelector((state) => state.Products.response_code);
  const response_message = useSelector(
    (state) => state.Products.response_message
  );
  const productUpdated = useSelector((state) => state.Products.updated);
  const [product, setProduct] = useState(productToEdit ? productToEdit : null);
  // const [errors, setErrors] = useState();

  const dispatch = useDispatch();

  //Retrieve categories
  const [categories, setCategories] = useState([]);
  const categoriesActionsApi = useApi(categoriesApi.categoriesAction);
  const getCategories = async () => {
    await categoriesActionsApi.request({
      action: "GetAllCategories",
    });
  };

  useEffect(() => {
    getCategories();
  }, []);

  useEffect(() => {
    if (categoriesActionsApi.data && categoriesActionsApi.data.length) {
      setCategories(
        categoriesActionsApi.data.map((i) => ({ label: i.title, value: i.id }))
      );
    }

    console.log("countriesActionsApi.data", categoriesActionsApi.data);
  }, [categoriesActionsApi.data]);

  useEffect(() => {
    if (productUpdated === true) {
      setUpdated(productUpdated);
      setisModalOpen(false);
      dispatch(resetRedux());
    }
  }, [productUpdated]);

  //Retrieve generics
  const [generics, setGenerics] = useState([]);
  const genericsActionsApi = useApi(genericsApi.genericsAction);
  const getGenerics = async () => {
    await genericsActionsApi.request({
      action: "GetGenerics",
    });
  };

  useEffect(() => {
    getGenerics();
  }, []);

  useEffect(() => {
    if (genericsActionsApi.data && genericsActionsApi.data.length) {
      setGenerics(
        genericsActionsApi.data.map((i) => ({ label: i.title, value: i.id }))
      );
    }
    console.log("generics", generics);
  }, [genericsActionsApi.data]);

  //

  const preparationsActionsApi = useApi(preparationsApi.preparationsAction);

  useEffect(() => {}, [product]);

  useEffect(() => {
    if (preparationsActionsApi.data) {
      if (preparationsActionsApi.data.category) {
        setProduct(preparationsActionsApi.data.category);
      }
    }
  }, [preparationsActionsApi.data]);

  useEffect(() => {
    if (errors && errors.length) {
      errors.map((x) => {
        toast.error(x);
      });
    }
  }, [errors]);

  const formik = useFormik({
    initialValues: {
      images: [],
      title: product ? product.title : "",
      units_per_pack: product ? product.units_per_pack : "",
      bar_code: product ? product.bar_code : "",
      packaging: product ? product.packaging : "",
      description: product ? product.description : "",
      category: product
        ? { label: product.category_title, value: product.category }
        : { label: "Select category", value: "" },
      preparation: product
        ? { label: product.preparation_title, value: product.manufacturer }
        : { label: "Search preparation by name (optional)", value: "" },
      manufacturer: product
        ? { label: product.manufacturer_title, value: product.manufacturer }
        : { label: "Search manufacturer by name", value: "" },
    },

    validationSchema: Yup.object({
      title: Yup.string()
        .min(3, "Must be 15 characters or more")
        .required("Title is required"),

      images: Yup.array().label("Images"),
    }),
    onSubmit: (values, { resetForm }) => {
      //Dispatch action

      //Generate form data to automatically encode data for upload using axios
      let data = new FormData();
      data.append("units_per_pack", values.units_per_pack);
      data.append("packaging", values.packaging);
      data.append("manufacturer", values.manufacturer.value);
      data.append("category", values.category.value);
      data.append("title", values.title);
      data.append("description", values.description);
      data.append("bar_code", values.bar_code);

      if (values.preparation) {
        data.append("preparation", values.preparation.value);
      }

      values.images.map((x) => {
        data.append("images", x);
      });

      if (productToEdit) {
        dispatch(updateProduct(data, productToEdit.id));
      } else {
        dispatch(addProduct(data));
      }
    },
  });

  //Load manufacturers

  const searchManufacturerApi = useApi(entitiesApi.entitiesAction);

  const searchManufacturers = async (data) => {
    await searchManufacturerApi.request(data);
  };
  const [manufacturers, setManufacturers] = useState();
  const loadManufacturerOptions = async (inputText = "", callback) => {
    searchManufacturers({
      action: "SearchManufacturers",
      searchQuery: inputText,
    });
    callback(manufacturers.map((i) => ({ label: i.title, value: i.id })));
  };

  useEffect(() => {
    if (searchManufacturerApi.data) {
      if (searchManufacturerApi.data.length) {
        setManufacturers(searchManufacturerApi.data);
      }
    }
    console.log("searchManufacturerApi.data", searchManufacturerApi.data);
  }, [searchManufacturerApi.data]);

  //Load preparations

  const searchPreparationApi = useApi(preparationsApi.preparationsAction);

  const searchPreparations = async (data) => {
    await searchPreparationApi.request(data);
  };

  const [preparations, setPreparations] = useState();

  useEffect(() => {
    if (searchPreparationApi.data) {
      if (searchPreparationApi.data.length) {
        setPreparations(searchPreparationApi.data);
      }
    }
  }, [searchPreparationApi.data]);

  const loadPreparationOptions = async (inputText = "", callback) => {
    searchPreparations({
      action: "SearchPreparations",
      searchQuery: inputText,
    });

    callback(preparations.map((i) => ({ label: i.title, value: i.id })));
  };

  const handleRemoveSelectedImage = (file) => {
    console.log("file", file);
    // formik.values.images.filter((x) => x.preview !== file.preview);

    formik.setFieldValue(
      "images",
      formik.values.images.filter((x) => x.preview !== file.preview)
    );
  };

  const handleOk = () => {
    setisModalOpen(false);
  };
  const handleCancel = () => {
    setisModalOpen(false);
  };

  return (
    <div className="w-full">
      <Modal
        width={560}
        className="w-full text-center"
        title={productToEdit ? `EDIT ${productToEdit.title}` : modalTitle}
        open={ismodalOpen}
        onOk={handleOk}
        onCancel={handleCancel}
        cancelButtonProps={{ style: { display: "none" } }}
        okButtonProps={{ style: { display: "none" } }}
      >
        <ToastContainer theme="colored" position="bottom-center" />

        <CustomForm
          layout="vertical"
          handleFinish={formik.handleSubmit}
          className=" flex flex-col justify-center items-center w-full my-7"
        >
          <CustomFormItem
            touched={formik.touched.title}
            error={formik.errors.title}
          >
            <CustomInput
              required={true}
              id="title"
              name="title"
              onChange={formik.handleChange}
              placeholder="Enter product title"
              size="large"
              type="text"
              value={formik.values.title}
              label="Product title"
            />
          </CustomFormItem>

          <CustomFormItem
            touched={formik.touched.bar_code}
            error={formik.errors.bar_code}
          >
            <CustomInput
              id="bar_code"
              name="bar_code"
              onChange={formik.handleChange}
              placeholder="Scan product bar code"
              size="large"
              type="text"
              value={formik.values.bar_code}
              label="Scan bar code"
            />
          </CustomFormItem>

          <CustomFormItem
            touched={formik.touched.units_per_pack}
            error={formik.errors.units_per_pack}
          >
            <CustomInput
              required={true}
              id="units_per_pack"
              name="units_per_pack"
              onChange={formik.handleChange}
              placeholder="Enter product units per pack"
              size="large"
              type="number"
              value={formik.values.units_per_pack}
              label="Product units per pack"
            />
          </CustomFormItem>

          <CustomFormItem
            touched={formik.touched.packaging}
            error={formik.errors.packaging}
          >
            <CustomInput
              required={true}
              id="packaging"
              name="packaging"
              onChange={formik.handleChange}
              placeholder="Enter product packaging"
              size="large"
              type="number"
              value={formik.values.packaging}
              label="Product packaging e.g. 10's"
            />
          </CustomFormItem>

          <CustomFormItem
            touched={formik.touched.category}
            error={formik.errors.category}
          >
            <CustomSelectReactSelect
              className="text-start"
              name="category"
              id="category"
              label="Select category"
              size="large"
              onChange={(value) => formik.setFieldValue("category", value)}
              value={formik.values.county}
              placeholder="Select category"
              options={categories}
            />
          </CustomFormItem>

          <CustomFormItem
            touched={formik.touched.preparation}
            error={formik.errors.preparation}
          >
            <CustomSelectAsyncSelect
              placeholder="Search  preparation by name (optional)"
              isClearable
              value={formik.values.preparation}
              onChange={(value) => formik.setFieldValue("preparation", value)}
              loadOptions={loadPreparationOptions}
            />
          </CustomFormItem>
          <CustomFormItem
            touched={formik.touched.manufacturer}
            error={formik.errors.manufacturer}
          >
            <CustomSelectAsyncSelect
              placeholder="Search  manufacturer by name (optional)"
              isClearable
              value={formik.values.manufacturer}
              onChange={(value) => formik.setFieldValue("manufacturer", value)}
              loadOptions={loadManufacturerOptions}
            />
          </CustomFormItem>
          <CustomFormItem
            touched={formik.touched.description}
            error={formik.errors.description}
          >
            <CustomTextArea
              required={true}
              id="description"
              name="description"
              onChange={formik.handleChange}
              placeholder="Enter product description"
              size="large"
              type="number"
              value={formik.values.description}
              label="Product packaging e.g. 10's"
            />
          </CustomFormItem>

          <div className="bg-white">
            <FileUploader
              placeholder="Select product images"
              formik={formik}
              name="images"
              types=".png,.jpg,.jpeg"
              value={formik.values.images}
              accept={{
                "image/png": [".png"],
                "image/jpeg": [".jpeg"],
              }}
            />
            {formik.values.images && formik.values.images.length > 0 && (
              <div className="shadow-md rounded my-5 bg-zinc-100 p-5">
                <h2 className="text-center font-bold mb-5">
                  Images selected for upload
                </h2>
                <div className="container flex flex-wrap mx-auto">
                  <div className="grid grid-cols-4 gap-2 sm:grid-cols-4 gap-3">
                    {formik.values.images?.map((file) => (
                      <div className="md:shrink-0 rounded " key={file.preview}>
                        <button
                          onClick={() => handleRemoveSelectedImage(file)}
                          className="flex  absolute text-red-800 border-red-800 border"
                        >
                          x
                        </button>
                        <img
                          className="h-10 w-full object-cover md:h-full md:w-48 shadow-md"
                          src={file.preview}
                          alt=""
                        />
                      </div>
                    ))}
                  </div>
                </div>
              </div>
            )}
          </div>

          <div className="w-full items-center mt-2">
            <Button className="w-36 rounded-md" color="primary" type="submit">
              Submit
            </Button>
          </div>
        </CustomForm>
      </Modal>
    </div>
  );
}
